// Generates client/src/theme/palette.ts and client/src/theme/palette.css
// from the single palette source assets/palette.json (ART_DIRECTION §2).
// No dependencies; deterministic output; exits non-zero on malformed
// input. Run with `npm run gen:palette`; the generated files are committed
// and CI checks that they are up to date.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

/** Groups every palette must have, with the roles each must define. */
export const REQUIRED = {
  terrain: ["sand", "grass-a", "grass-b", "dry", "forest-floor", "mountain", "cliff"],
  water: ["shallows", "deep", "foam", "haze"],
  buildings: ["plaster", "ochre", "timber", "thatch", "terracotta", "slate", "stone", "brass"],
  ui: ["parchment", "dark-wood", "brass", "ink"],
  status: [],
  light: ["sun", "sky"],
};

const HEX = /^#[0-9A-F]{6}$/;
const NAME = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;

/** kebab-case role name → TS key (snake_case, so status keys equal the StatusKey names). */
const tsKey = (name) => name.replace(/-/g, "_");
/** Group name → TS constant name. */
const tsConst = (group) => group.replace(/-/g, "_").toUpperCase();

/**
 * Validates a parsed palette and returns the generated TypeScript and CSS
 * text. Throws an Error naming the first problem.
 */
export function generatePalette(palette) {
  if (typeof palette !== "object" || palette === null || Array.isArray(palette)) throw new Error("palette: not an object");
  if (!Number.isInteger(palette.version) || palette.version < 1) throw new Error("palette: version must be a positive integer");
  const groups = palette.groups;
  if (typeof groups !== "object" || groups === null || Array.isArray(groups)) throw new Error("palette: missing groups");
  for (const [g, roles] of Object.entries(REQUIRED)) {
    if (!(g in groups)) throw new Error(`palette: missing group "${g}"`);
    for (const r of roles) {
      if (!(r in (groups[g]?.colors ?? {}))) throw new Error(`palette: group "${g}" lacks "${r}"`);
    }
  }
  const ts = [
    "// Generated by scripts/gen-palette.mjs from assets/palette.json — do not edit.",
    "// Run `npm run gen:palette` after changing the palette.",
    "",
    `export const PALETTE_VERSION = ${palette.version};`,
  ];
  const css = [
    "/* Generated by scripts/gen-palette.mjs from assets/palette.json — do not edit. */",
    "/* Run `npm run gen:palette` after changing the palette. */",
    "",
    ":root {",
  ];
  for (const [g, group] of Object.entries(groups)) {
    if (!NAME.test(g)) throw new Error(`palette: group name "${g}" is not kebab-case`);
    if (typeof group !== "object" || group === null) throw new Error(`palette: group "${g}" is not an object`);
    if (typeof group.description !== "string" || group.description.trim() === "" || group.description.includes("\n")) {
      throw new Error(`palette: group "${g}" needs a one-line description`);
    }
    const colors = group.colors;
    if (typeof colors !== "object" || colors === null || Array.isArray(colors) || Object.keys(colors).length === 0) {
      throw new Error(`palette: group "${g}" has no colors`);
    }
    ts.push("", `/** ${group.description} */`, `export const ${tsConst(g)} = {`);
    for (const [name, value] of Object.entries(colors)) {
      if (!NAME.test(name)) throw new Error(`palette: ${g}.${name} is not kebab-case`);
      if (typeof value !== "string" || !HEX.test(value)) throw new Error(`palette: ${g}.${name} must be a 6-digit upper-case hex colour, got ${JSON.stringify(value)}`);
      ts.push(`  ${tsKey(name)}: "${value}",`);
      css.push(`  --ns-${g}-${name}: ${value};`);
    }
    ts.push("} as const;");
    if (group.values !== undefined) {
      if (typeof group.values !== "object" || group.values === null || Array.isArray(group.values)) throw new Error(`palette: ${g}.values is not an object`);
      ts.push("", `export const ${tsConst(g)}_VALUES = {`);
      for (const [name, value] of Object.entries(group.values)) {
        if (!NAME.test(name)) throw new Error(`palette: ${g}.${name} is not kebab-case`);
        if (typeof value !== "number" || !Number.isFinite(value)) throw new Error(`palette: ${g}.values.${name} must be a number`);
        ts.push(`  ${tsKey(name)}: ${value},`);
        css.push(`  --ns-${g}-${name}: ${value};`);
      }
      ts.push("} as const;");
    }
  }
  css.push("}");
  return { ts: `${ts.join("\n")}\n`, css: `${css.join("\n")}\n` };
}

function main() {
  const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
  const src = join(root, "assets", "palette.json");
  const out = join(root, "client", "src", "theme");
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(src, "utf8"));
  } catch (err) {
    throw new Error(`palette: cannot read ${src}: ${err.message}`);
  }
  const { ts, css } = generatePalette(parsed);
  writeFileSync(join(out, "palette.ts"), ts);
  writeFileSync(join(out, "palette.css"), css);
  console.log(`palette v${parsed.version} written to ${out}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    main();
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
}
